---@param isShowBlack boolean
function PVPArenaPlayerInfoNode:RefreshUI(info, playerId, isShowBlack)

    self.TxtLV.text = localize("<size=13>LV</size>_num_", {_num_ = info.level})

    self.TxtplayerName.text = info.name
    self.TxtplayerName.color = XLuaUtils.HexToColor(isShowBlack and "#949494" or "#eaeaea")

    KTool.SetActive(self.black.gameObject, isShowBlack)

    PVPArenaUtils.RefreshPlayerHeadNode(self.PlayerHeadNode.gameObject, playerId, info, nil, Bind(self, self.OnClickHeadNodeAction))
end
